CREATE TABLE IF NOT EXISTS "PROFESORES_CATALOGO" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NOMBRE" VARCHAR(120) NOT NULL,
    "RUD" VARCHAR(20) NOT NULL UNIQUE,
    "APELLIDO" VARCHAR(120) NOT NULL,
    "DIRECCION" VARCHAR(250),
    "EMAIL" VARCHAR(180) NOT NULL UNIQUE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS "PROFESOR_ASIGNATURAS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PROFESOR_ID" BIGINT NOT NULL,
    "ASIGNATURA" VARCHAR(120) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_PROFESOR_ASIGNATURAS_PROFESORES" FOREIGN KEY ("PROFESOR_ID") REFERENCES "PROFESORES_CATALOGO" ("ID")
);

CREATE TABLE IF NOT EXISTS "CURSO_DOCENTES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CURSO_ID" BIGINT NOT NULL UNIQUE,
    "PROFESOR_ID" BIGINT NOT NULL,
    "ASISTENTE_ID" BIGINT,
    CONSTRAINT "FK_CURSO_DOCENTES_CURSOS" FOREIGN KEY ("CURSO_ID") REFERENCES "CURSOS" ("ID"),
    CONSTRAINT "FK_CURSO_DOCENTES_PROFESOR" FOREIGN KEY ("PROFESOR_ID") REFERENCES "PROFESORES_CATALOGO" ("ID"),
    CONSTRAINT "FK_CURSO_DOCENTES_ASISTENTE" FOREIGN KEY ("ASISTENTE_ID") REFERENCES "PROFESORES_CATALOGO" ("ID")
);

INSERT INTO "PROFESORES_CATALOGO" ("NOMBRE", "RUD", "APELLIDO", "DIRECCION", "EMAIL", "ACTIVO")
SELECT * FROM (
    VALUES
        ('Juan', '11.111.111-1', 'Perez Soto', 'Av. Central 123', 'juan.perez@colegio.cl', TRUE),
        ('Maria', '22.222.222-2', 'Gonzalez Rojas', 'Calle Los Aromos 456', 'maria.gonzalez@colegio.cl', TRUE),
        ('Carolina', '33.333.333-3', 'Munoz Diaz', 'Pasaje El Roble 88', 'carolina.munoz@colegio.cl', TRUE),
        ('Diego', '44.444.444-4', 'Silva Torres', 'Los Canelos 15', 'diego.silva@colegio.cl', TRUE),
        ('Paula', '55.555.555-5', 'Contreras Vega', 'Villa Escolar 322', 'paula.contreras@colegio.cl', TRUE)
) AS v("NOMBRE", "RUD", "APELLIDO", "DIRECCION", "EMAIL", "ACTIVO")
