INSERT INTO "PROFESOR_ASIGNATURAS" ("PROFESOR_ID", "ASIGNATURA", "ACTIVO")
SELECT p."ID", v."ASIGNATURA", TRUE
FROM (
    VALUES
        ('11.111.111-1', 'Matematicas'),
        ('11.111.111-1', 'Ciencias'),
        ('22.222.222-2', 'Lenguaje'),
        ('22.222.222-2', 'Historia'),
        ('33.333.333-3', 'Artes'),
        ('33.333.333-3', 'Tecnologia'),
        ('44.444.444-4', 'Educacion fisica'),
        ('55.555.555-5', 'Ingles'),
        ('55.555.555-5', 'Lenguaje')
) AS v("RUD", "ASIGNATURA")
JOIN "PROFESORES_CATALOGO" p ON p."RUD" = v."RUD"
WHERE NOT EXISTS (
    SELECT 1
    FROM "PROFESOR_ASIGNATURAS" pa
    WHERE pa."PROFESOR_ID" = p."ID"
      AND pa."ASIGNATURA" = v."ASIGNATURA"
);
